-- Metadata-only subset of the production schema for isolated transaction tests.
create table public.audit_logs (id uuid not null default gen_random_uuid(), organization_id uuid  , action text not null , entity_type text not null , entity_id uuid  , details jsonb not null default '{}'::jsonb, "timestamp" timestamptz not null default now(), primary key(id));
create table public.clinical_documents (id uuid not null default gen_random_uuid(), organization_id uuid not null , patient_id uuid not null , title text not null , document_type text not null , mime_type text not null , file_size_bytes int8 not null , storage_path text not null , current_version_number int4 not null default 1, quarantine_status text not null default 'validated'::text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), primary key(id));
create table public.clinical_reviews (id uuid not null default gen_random_uuid(), organization_id uuid not null , alert_id uuid not null , reviewer_id uuid not null , reviewer_role text not null , review_decision text not null , clinical_rationale text not null , created_at timestamptz not null default now(), primary key(id));
create table public.consent_records (id uuid not null default gen_random_uuid(), organization_id uuid not null , patient_id uuid not null , consent_type text not null , status text not null default 'granted'::text, granted_by uuid not null , valid_until timestamptz  , created_at timestamptz not null default now(), primary key(id));
create table public.discharge_instructions (id uuid not null default gen_random_uuid(), organization_id uuid not null , patient_id uuid not null , encounter_id uuid  , primary_language text not null default 'en'::text, dietary_guidelines text  , activity_restrictions text  , follow_up_appointments jsonb  default '[]'::jsonb, warning_symptoms jsonb  default '[]'::jsonb, is_verified bool not null default false, verified_by uuid  , created_at timestamptz not null default now(), updated_at timestamptz not null default now(), primary key(id));
create table public.discharge_translations (id uuid not null default gen_random_uuid(), organization_id uuid not null , instruction_id uuid not null , language_code text not null , translated_content jsonb not null , translation_engine text not null default 'human_verified_draft'::text, is_professionally_approved bool not null default false, approved_by uuid  , approved_at timestamptz  , created_at timestamptz not null default now(), primary key(id));
create table public.encounters (id uuid not null default gen_random_uuid(), organization_id uuid not null , patient_id uuid not null , encounter_number text not null , encounter_type text not null , status text not null default 'active'::text, admission_date timestamptz not null , created_at timestamptz not null default now(), updated_at timestamptz not null default now(), primary key(id));
create table public.organization_members (id uuid not null default gen_random_uuid(), organization_id uuid not null , user_id uuid not null , role_id text not null , department text  , is_active bool not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), primary key(id));
create table public.patients (id uuid not null default gen_random_uuid(), organization_id uuid not null , mrn text not null , first_name text not null , last_name text not null , date_of_birth date not null , gender text  , is_synthetic bool not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), primary key(id));
create table public.profiles (id uuid not null , full_name text not null , email text not null , phone text  , avatar_url text  , created_at timestamptz not null default now(), updated_at timestamptz not null default now(), primary key(id));
create table public.safety_alerts (id uuid not null default gen_random_uuid(), organization_id uuid not null , patient_id uuid not null , severity text not null , title text not null , summary text not null , status text not null default 'pending_review'::text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), primary key(id));
alter table patients add unique(id,organization_id);
alter table organization_members add unique(organization_id,user_id);
create table public.clinical_entities (id uuid not null default gen_random_uuid(), organization_id uuid not null , document_version_id uuid not null , patient_id uuid not null , entity_type text not null , raw_text text not null , normalized_code text  , normalized_name text  , source_location jsonb not null default '{}'::jsonb, confidence_score numeric  , is_verified bool not null default false, created_at timestamptz not null default now(), primary key(id));
create table public.document_versions (id uuid not null default gen_random_uuid(), organization_id uuid not null , document_id uuid not null , version_number int4 not null , sha256_hash text not null , storage_path text not null , created_at timestamptz not null default now(), primary key(id));
create table public.evidence_edges (id uuid not null default gen_random_uuid(), organization_id uuid not null , patient_id uuid not null , source_node_id uuid not null , target_node_id uuid not null , relationship_type text not null , weight numeric  default 1.0, provenance_notes text  , created_at timestamptz not null default now(), primary key(id));
create table public.evidence_nodes (id uuid not null default gen_random_uuid(), organization_id uuid not null , patient_id uuid not null , node_type text not null , reference_id uuid not null , label text not null , metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), primary key(id));
create table public.extraction_jobs (id uuid not null default gen_random_uuid(), organization_id uuid not null , document_version_id uuid not null , status text not null default 'queued'::text, model_version text  , started_at timestamptz  , completed_at timestamptz  , error_message text  , metadata jsonb  default '{}'::jsonb, created_at timestamptz not null default now(), primary key(id));
